import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  color,
  mix,
  smoothstep,
  sin,
  fract,
  dot,
  min,
  max,
  length,
  sub,
  uniform,
} from 'three/tsl';
import { gsap } from 'gsap';

// Nova Atelier — Primary CTA (decorative, static, no interactivity)
// Machined-metal card + engineered gradient + subtle grain + orb-decor overlay.

function buildRoundedRectShape(THREE, w, h, r) {
  const shape = new THREE.Shape();
  const x = -w / 2;
  const y = -h / 2;
  shape.moveTo(x, y + r);
  shape.lineTo(x, y + h - r);
  shape.quadraticCurveTo(x, y + h, x + r, y + h);
  shape.lineTo(x + w - r, y + h);
  shape.quadraticCurveTo(x + w, y + h, x + w, y + h - r);
  shape.lineTo(x + w, y + r);
  shape.quadraticCurveTo(x + w, y, x + w - r, y);
  shape.lineTo(x + r, y);
  shape.quadraticCurveTo(x, y, x, y + r);
  return shape;
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, ExtrudeGeometry, Vector2, DoubleSide } = THREE;

  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'primary-cta';

  // ---- dimensions ----
  const width = 2.2;
  const height = 0.72;
  const depth = 0.09;
  const radius = 0.12;

  // ---- contact shadow (grounding) ----
  const shadowGeo = new PlaneGeometry(width * 1.5, height * 2.0, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  {
    const suv = uv();
    const d = length(sub(suv, vec2(0.5, 0.5)).mul(vec2(1.0, 0.7)));
    const alpha = smoothstep(0.5, 0.0, d).mul(0.5);
    shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
    shadowMat.opacityNode = alpha;
  }
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -height * 0.55, -depth * 1.5);
  shadowMesh.renderOrder = -1;
  group.add(shadowMesh);

  // ---- machined-metal card (engineered gradient + subtle grain + accent edge) ----
  const shape = buildRoundedRectShape(THREE, width, height, radius);
  const cardGeo = new ExtrudeGeometry(shape, {
    depth,
    bevelEnabled: true,
    bevelThickness: 0.015,
    bevelSize: 0.015,
    bevelSegments: 2,
    curveSegments: 8,
  });
  cardGeo.center();

  const cardMat = new MeshPhysicalNodeMaterial({ side: DoubleSide });
  cardMat.metalness = 0.45;
  cardMat.roughness = 0.55;
  cardMat.clearcoat = 0.18;
  cardMat.clearcoatRoughness = 0.4;

  {
    const cuv = uv();
    const inkC = color(palette.ink);
    const surfaceC = color(palette.surface);
    const accentC = color(palette.accent);

    const gradT = smoothstep(0.0, 1.0, cuv.y);
    const base = mix(surfaceC, inkC, gradT);

    // subtle static grain (no time dependency -> static composition)
    const grainSeed = dot(cuv.mul(650.0), vec2(12.9898, 78.233));
    const grain = fract(sin(grainSeed).mul(43758.5453));
    const grained = mix(base, vec3(1.0, 1.0, 1.0), grain.mul(0.035));

    // thin accent edge along the bottom of the card (<=10% of frame area)
    const edgeDist = min(cuv.y, min(sub(1.0, cuv.y), min(cuv.x, sub(1.0, cuv.x))));
    const edgeFactor = smoothstep(0.05, 0.0, edgeDist);
    const withEdge = mix(grained, accentC, edgeFactor.mul(0.85));

    cardMat.colorNode = withEdge;
    cardMat.emissiveNode = accentC.mul(edgeFactor.mul(0.5));
  }

  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.castShadow = false;
  group.add(cardMesh);

  // ---- decorative orb overlay (imageUrl) ----
  const orbSize = 0.5;
  const orbGeo = new PlaneGeometry(orbSize, orbSize, 1, 1);
  const orbMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  orbMat.colorNode = vec3(1.0, 1.0, 1.0);
  orbMat.opacityNode = uniform(0.0); // fades in once texture arrives
  const orbMesh = new Mesh(orbGeo, orbMat);
  orbMesh.position.set(width * 0.32, 0, depth * 0.7 + 0.02);
  group.add(orbMesh);

  let orbTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      orbTexture = tex;
      orbMat.colorNode = null;
      orbMat.map = tex;
      orbMat.opacityNode = null;
      orbMat.transparent = true;
      orbMat.opacity = 0;
      orbMat.needsUpdate = true;
      gsap.to(orbMat, { opacity: 1, duration: 0.6, ease: 'power2.out' });
    });
  }

  // ---- scene placement (adapter applies scenePosition; local rotation/scale only if authored) ----
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // ---- weighted-settle entrance (one-time, non-perpetual) ----
  group.scale.setScalar(0.0001);
  const tl = gsap.timeline();
  tl.to(group.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.45,
    ease: 'power3.out',
  }).to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.45,
    ease: 'power4.out',
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(orbMat);
    gsap.killTweensOf(group.scale);

    shadowGeo.dispose();
    shadowMat.dispose();

    cardGeo.dispose();
    cardMat.dispose();

    orbGeo.dispose();
    orbMat.dispose();
    if (orbTexture && orbTexture.dispose) orbTexture.dispose();
  };

  return group;
}
